catalog_script_client.script:
function onSubmit() {
    try {
        var mrvsJSON = g_form.getValue('menu_items');

        if (!mrvsJSON) {
            console.log("MRVS is empty or not found.");
            return true;
        }

        var rows = JSON.parse(mrvsJSON);
        var totalCost = 0;

        for (var i = 0; i < rows.length; i++) {
            var price = rows[i].food_price;
            if (price) {
                var parsed = parseFloat(price.trim());
                if (!isNaN(parsed)) {
                    totalCost += parsed;
                }
            }
        }

        alert("Total: " + totalCost.toFixed(2));

        if (typeof cat_g_form !== 'undefined') {
            cat_g_form.setValue('total_price', totalCost.toFixed(2));
        } else {
            parent.g_form.setValue('total_price', totalCost.toFixed(2));
        }

    } catch (e) {
        console.log("Submit error: " + e.message);
    }

    return true;
}
